def create_existing_cycles(apps, schema_editor):
    alias = schema_editor.connection.alias
    planting = apps.get_model('garden', 'Planting')
    cycle = apps.get_model('garden', 'PlantingCycle')
    year = timezone.localdate().year
    records = planting.objects.using(alias).order_by('batch_key', 'pk').iterator(chunk_size=500)
    priority = {'completed': 0, 'planned': 1, 'ongoing': 2}
    for key, members in groupby(records, key=lambda record: record.batch_key):
        statuses = []
        for member in members:
            if member.start_year > year:
                status = 'planned'
            elif (member.lifespan == 'annual' and member.start_year < year) or (
                member.lifespan == 'persistent' and member.end_year is not None and member.end_year < year
            ):
                status = 'completed'
            else:
                status = 'ongoing'
            statuses.append(status)
        cycle.objects.using(alias).create(id=key, status=max(statuses, key=priority.get))
        planting.objects.using(alias).filter(batch_key=key).update(cycle_id=key)


